func firstIndex(from day: Int, in workouts: [Workout]) -> Int {
    var low = 0
    var high = workouts.count
    while low < high {
        let mid = low + (high - low) / 2
        if workouts[mid].day < day {
            low = mid + 1
        } else {
            high = mid
        }
    }
    return low
}

